parameters.functionCode:
// Extract appointment data from webhook
const appointment = $input.first().json.appointment;
const patientInfo = appointment.patientId || {};

// Prepare email data
return {
  patientEmail: patientInfo.email || '',
  patientName: `${patientInfo.firstName || ''} ${patientInfo.lastName || ''}`.trim(),
  doctorName: appointment.doctorName || 'Your Doctor',
  appointmentDate: appointment.date,
  appointmentTime: appointment.time,
  appointmentType: appointment.type || 'checkup',
  location: appointment.location || 'Medical Center',
  isVideoCall: appointment.isVideoCall || false,
  appointmentId: appointment._id
};

parameters.text:
Dear {{ $node['Prepare Email Data'].json.patientName }},

Your appointment has been confirmed!

Appointment Details:
- Date: {{ $node['Prepare Email Data'].json.appointmentDate }}
- Time: {{ $node['Prepare Email Data'].json.appointmentTime }}
- Type: {{ $node['Prepare Email Data'].json.appointmentType }}
- Doctor: {{ $node['Prepare Email Data'].json.doctorName }}
- Location: {{ $node['Prepare Email Data'].json.location }}
{% if $node['Prepare Email Data'].json.isVideoCall %}
- This is a video call appointment. Link will be sent separately.
{% endif %}

Please arrive 15 minutes early and bring your ID and insurance card.

If you need to reschedule or cancel, please call us at least 24 hours in advance.

Thank you,
MediFollow Team

